/* eslint-disable camelcase */
import React, { useEffect } from 'react';
import { WarningOutlined } from '@ant-design/icons';
import { Modal, Button } from 'antd';
import { useDispatch, useSelector } from 'react-redux'
// import Router from 'next/router'
import { changeCommonValue } from 'redux/actions/common'
import { showIntercom } from 'Utils/constants/index'
import { useRestrictionContext } from 'components/IntegratePages/layout/context/restrictionContext';

const secondsToGo = 5
const CustomPopup = ({
  isVisible_custom_popup,
  handleCsrfAndQuoteModelVisible,
}) => {
  const dispatch = useDispatch()
  const commonReducer = useSelector((state) => state.commonReducer)
  const {modalMessage} = commonReducer;

  const { setShowPricingModal } = useRestrictionContext();

  useEffect(() => {
   const timer = setTimeout(() => {
      dispatch(changeCommonValue('isVisible_custom_popup', false, '...'))
    }, secondsToGo * 1000)
    return () => { clearTimeout(timer)}
  }, [])
  return <Modal
  wrapClassName='app-restriction-modal'
  style={{ top: 10 }}
  mask={false}
  className={modalMessage ? 'limit-message-box' : 'message-on-modal'}
  visible={isVisible_custom_popup}
  onCancel={() =>
    dispatch(changeCommonValue('isVisible_custom_popup', false, '...'))
  }
  footer={null}
>
  {modalMessage ? (
    <>
      <div className='modal-body' style={{ padding: 0 }}>
        <span>{modalMessage}</span>
      </div>
      <div className='modal-footer'>
        <div className='btn-wrapper'>
          <Button
            onClick={async (e) => {
              handleCsrfAndQuoteModelVisible(e)
              dispatch(changeCommonValue('isVisible_custom_popup', false, '...'))
              setShowPricingModal(true)
            }}
            type="primary"
            style={{ width: 130 }}
          >
            Request Upgrade
          </Button>
          <Button
            onClick={() =>
              dispatch(changeCommonValue('isVisible_custom_popup', false, '...'))
            }
            type="primary"
          >
            Got it
          </Button>
      </div>
      </div>
    </>
  ) : (
    <>
      <div className='message-icon'>
        <WarningOutlined />
      </div>
      <p className='error-title' style={{ marginBottom: '5px' }}>
        <strong>
          Google reCaptcha reported suspicious activity on this page.
        </strong>
      </p>
      <p>
        Please try again in a few minutes or different browser or device.
        Get in touch with
        <br />
        <a href='#!' onClick={() => showIntercom()}>our team</a> if the issue
        persists.
      </p>
    </>
  )}
  <style>
    {`
      .modal-footer {
        display: flex;
      }
    `}
  </style>
</Modal>;
}
export default CustomPopup
